                        asm volatile("st.shared.b32 [%0], %1;" :: "r"((smem_inv_addr + prep_stage * 107520 + (unsigned int)(publish_segment * 8 / 16 * 2048 + publish_row_1 * 32 + publish_segment * 8 % 16 * 2 ^ (publish_segment * 8 / 16 * 2048 + publish_row_1 * 32 + publish_segment * 8 % 16 * 2 >> 7 & 1) << 4)) + (unsigned int)(word_10 * 4)), "r"((packed_6[word_10])));
                    }
                }
                asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
                asm volatile("barrier.sync %0, 128;" :: "r"(10 + prep_instance) : "memory");
                if (prep_local_warp == 0) {
                    if (elect_sync()) {
                        mbarrier_arrive(qk_full_addr + (prep_stage) * 8);
                    }
                }
                if (chunk_is_full_1 != 0) {
                    if (prep_local_warp == 0) {
                        if (elect_sync()) {
                            mbarrier_arrive_expect_tx(v_full_addr + (prep_stage) * 8, 16384);
                            tma_3d_gmem2smem(smem_v_addr + prep_stage * 107520, v_tma, 0, head_idx_2, (int)(bos_3 + (long long)(chunk_idx_2 * 64)), v_full_addr + (prep_stage) * 8);
                        }
                    }
                } else {
                    #pragma unroll
                    for (int v_load_iter = 0; v_load_iter < 8; v_load_iter++) {
                        int v_item = v_load_iter * 128 + prep_tid;
                        int row_1 = v_item / 16;
                        int segment_1 = v_item % 16;
                        long long token_1 = bos_3 + (long long)(chunk_idx_2 * 64 + row_1);
                        int token_valid_1 = ((token_1 < eos_3) ? 1 : 0);
                        long long v_src = (token_1 * (long long)num_heads + (long long)head_idx_2) * 128 + (long long)(segment_1 * 8);
                        asm volatile("cp.async.cg.shared::cta.global [%0], [%1], 16, %2;"
                            :: "r"(smem_v_addr + prep_stage * 107520 + (unsigned int)((row_1 * 128 + segment_1 * 8) * 2)), "l"(v + v_src), "r"((token_valid_1 != 0) ? 16 : 0));
                    }
                    asm volatile("cp.async.commit_group;");
                    asm volatile("cp.async.wait_group 0;");
                    asm volatile("barrier.sync %0, 128;" :: "r"(10 + prep_instance) : "memory");
                    if (prep_local_warp == 0) {
                        if (elect_sync()) {
                            asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
                            mbarrier_arrive(v_full_addr + (prep_stage) * 8);
                        }
                    }
                }
                for (int _advance = 0; _advance < 2; _advance++) {
                    prep_stage += 1;
                    if (prep_stage == 2) { prep_stage = 0; _phase_raw_inputs_free ^= 1; _phase_gate_raw_full ^= 1; _phase_smem_free ^= 1; _phase_v_free ^= 1; _phase_qk_raw_full ^= 1; _phase_prep_diag_ready ^= 1; }
                }
            }
        }
    }
    // ---- Role: bt64_idle_donors ----
    if (warp >= 20 && warp <= 31) {
        asm volatile("setmaxnreg.dec.sync.aligned.u32 48;");
        // idle — no tasks assigned
    }

    // Cleanup
}

